scripts.folderClick:
(function(){
  try {
    var want = "relay garage";
    if (!want) return "not-found";
    var nodes = document.querySelectorAll('[role="treeitem"], [role="option"], nav a, div[role="navigation"] span');
    function labelOf(el){
      var t = (el.getAttribute("aria-label")||el.getAttribute("title")||el.innerText||"").trim();
      // strip a trailing numeric unread/total count badge, e.g. "DOMO 57" / "Inbox 1492".
      t = t.replace(/\s+\d[\d,]*\s*$/,"").trim();
      // some builds append ", <n> unread/items"; cut at the first comma.
      var comma = t.indexOf(","); if (comma > 0) t = t.slice(0, comma).trim();
      return t.toLowerCase();
    }
    for (var i=0;i<nodes.length;i++){
      if (labelOf(nodes[i]) === want){
        var click = nodes[i].querySelector('a,span,[role="button"]') || nodes[i];
        click.click();
        return "clicked";
      }
    }
    return "not-found";
  } catch(e){ return "error:"+String(e&&e.message||e); }
})();

