scripts.selectRow:
(function(){
  try {
    var cid = "AAQkAD/abc=";
    if (!cid) return "row-not-found";
    var rows = document.querySelectorAll("div[role=\"option\"][aria-label],div[data-convid],div[role=\"listitem\"],div[data-animation-id]");
    var row = null;
    for (var i=0;i<rows.length;i++){ if (rows[i].getAttribute("data-convid") === cid){ row = rows[i]; break; } }
    if (!row) return "row-not-found";
    var sel = row.querySelector('[role="button"], a, span') || row;
    sel.click();
    try { row.scrollIntoView({block:"center"}); } catch(e){}
    return "selected";
  } catch(e){ return "error:"+String(e&&e.message||e); }
})();

scripts.deleteClick:
(function(){
  try {
    // 1) Toolbar/command-bar Delete button (exact aria-label="Delete").
    var btn = document.querySelector('button[aria-label="Delete"]')
           || document.querySelector('button[aria-label^="Delete" i]')
           || document.querySelector('[role="menuitem"][aria-label^="Delete" i]');
    if (btn) { btn.click(); return "clicked:button"; }
    // 2) The Delete icon (DeleteRegularLight) — click its enclosing button.
    var ic = document.querySelector('i[data-icon-name*="Delete" i], span[data-icon-name*="Delete" i]');
    if (ic) { var b = ic.closest("button,[role=button]") || ic; b.click(); return "clicked:icon"; }
    // 3) Keyboard Delete as last resort.
    var ev = new KeyboardEvent("keydown", { key:"Delete", code:"Delete", keyCode:46, which:46, bubbles:true });
    (document.activeElement||document.body).dispatchEvent(ev);
    return "clicked:key";
  } catch(e){ return "error:"+String(e&&e.message||e); }
})();
